import sys, json, re, pathlib
path = sys.argv[1]
sections = [s.strip() for s in sys.argv[2].split(',') if s.strip()]
findings = []
text = ''
try:
    raw = pathlib.Path(path).read_bytes()
    try:
        if raw[:2] in (b'\xff\xfe', b'\xfe\xff'):
            text = raw.decode('utf-16')
        else:
            text = raw.decode('utf-8-sig')
    except ValueError:
        text = raw.decode('utf-8', errors='replace')
    if not text.strip():
        findings.append({'severity': 'blocker', 'category': 'empty-doc', 'file': path, 'line': None, 'claim': 'proposal file is empty', 'evidence': str(len(raw)) + ' byte(s), no text content', 'fix_hint': 'write the proposal before gating it'})
except OSError as e:
    findings.append({'severity': 'blocker', 'category': 'unreadable', 'file': path, 'line': None, 'claim': 'proposal file could not be read', 'evidence': str(e), 'fix_hint': 'check the --arg file= path'})
if text.strip():
    heads = [m.group(1).strip().lower() for m in re.finditer(r'^#{1,6}\s+(.+)$', text, re.M)]
    for s in sections:
        if not any(s.lower() in h for h in heads):
            findings.append({'severity': 'blocker', 'category': 'missing-section', 'file': path, 'line': None, 'claim': 'required section "' + s + '" not found', 'evidence': 'no markdown heading contains "' + s + '"', 'fix_hint': 'add a "## ' + s + '" section'})
verdict = 'pass' if not findings else 'block'
reason = 'all required sections present' if verdict == 'pass' else str(len(findings)) + ' structural problem(s)'
print(json.dumps({'findings': findings, 'verdict': verdict, 'reason': reason}))

